(()=>{const s='https://open.spotify.com/embed/show/4NluRPjuAIGK59vVf7GcoF';document.addEventListener('click',e=>{const b=e.target.closest('[data-spotify-load]');if(b){const w=b.closest('[data-spotify-facade]');if(w){const f=document.createElement('iframe');f.title="Turing's Torch on Spotify";f.src=s;f.loading='lazy';f.allow='autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture';w.replaceChildren(f)}return}const x=e.target.closest('[data-elfsight-load]');if(x){const h=x.closest('[data-elfsight-deferred]');if(!h||h.dataset.loaded)return;h.dataset.loaded='1';x.remove();const sc=document.createElement('script');sc.src='https://elfsightcdn.com/platform.js';sc.async=true;document.head.appendChild(sc)}})})();
